const $=s=>document.querySelector(s), canvas=$('#scene'),ctx=canvas.getContext('2d');ctx.imageSmoothingEnabled=false;
const fresh=()=>({money:80,day:1,energy:10,hour:8,minute:0,inventory:{},crops:[{seed:'carrot',stage:0,watered:false},{seed:null,stage:0,watered:false},{seed:null,stage:0,watered:false}],tool:'inspect',friends:{Maja:1,Oskar:0},quest:0,logs:['Maja hat dich herzlich willkommen geheißen.','Du bist auf deinem kleinen Hof angekommen.']});let state;try{state={...fresh(),...JSON.parse(localStorage.getItem('hofglueck-save')||'{}')};state.friends={...fresh().friends,...(state.friends||{})};state.inventory=state.inventory||{};state.crops=state.crops||fresh().crops}catch{state=fresh()}
const items={carrot:{name:'Karotte',emoji:'🥕',price:12},turnip:{name:'Rübe',emoji:'🫜',price:10},berry:{name:'Waldbeere',emoji:'🫐',price:8},wood:{name:'Holz',emoji:'🪵',price:5},stone:{name:'Stein',emoji:'🪨',price:4},fish:{name:'Sonnenbarsch',emoji:'🐟',price:18},herb:{name:'Wiesenkräuter',emoji:'🌿',price:7}};
let toastTimer;function toast(t){const el=$('#toast');el.textContent=t;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2100)}function save(){localStorage.setItem('hofglueck-save',JSON.stringify(state));renderUI()}function log(t){state.logs.unshift(t);state.logs=state.logs.slice(0,7)}function add(item,n=1){state.inventory[item]=(state.inventory[item]||0)+n}function spend(n){if(state.energy<n){toast('Du bist müde. Ruh dich aus oder komm morgen wieder!');return false}state.energy-=n;state.minute+=30;if(state.minute>=60){state.hour++;state.minute-=60}if(state.hour>=20){state.day++;state.hour=8;state.minute=0;state.energy=10;state.crops.forEach(c=>{if(c.seed&&c.stage<3)c.stage++;c.watered=false});log('Ein neuer Morgen im Sonnental! Deine Pflanzen sind ein Stück gewachsen.');toast('Ein neuer Morgen! Tatkraft ist wieder voll.')}return true}
const rand=(x,y)=>{let n=Math.sin(x*127.1+y*311.7)*43758.5453;return n-Math.floor(n)};
function rect(x,y,w,h,c){ctx.fillStyle=c;ctx.fillRect(Math.round(x),Math.round(y),Math.round(w),Math.round(h))}
function draw(){const c=ctx;c.clearRect(0,0,900,440);
// sky and distant hills
rect(0,0,900,230,'#b9dce0');rect(0,200,900,240,'#8eb778');rect(0,183,900,45,'#9cc88a');for(let i=0;i<7;i++){const x=i*150-30;rect(x,160+Math.sin(i*2)*22,130,76,'#a8cd91');rect(x+14,171+Math.sin(i*2)*22,100,51,'#acd294')}
// cloud clusters
for(const [x,y] of [[91,55],[350,82],[748,48]]){rect(x,y+9,52,15,'#f5f4e3');rect(x+9,y,23,20,'#f5f4e3');rect(x+28,y+4,18,16,'#f5f4e3');rect(x+6,y+19,40,4,'#e8ebd9')}
// back trees
for(let i=0;i<10;i++){let x=i*101+rand(i,1)*32-15,y=182+rand(i,2)*19;rect(x+12,y+27,10,42,'#8b6246');rect(x,y+4,34,32,i%2?'#63895c':'#719966');rect(x+5,y-7,25,26,i%2?'#739d69':'#7da871');rect(x+8,y+1,7,5,'#91bb79')}
// meadow patches
for(let i=0;i<52;i++){let x=rand(i,3)*890,y=220+rand(i,4)*205;rect(x,y,3,3,i%4===0?'#ead895':i%4===1?'#79a86d':i%4===2?'#bfd17e':'#f1e7a9')}
// path
ctx.beginPath();ctx.moveTo(517,440);ctx.lineTo(545,440);ctx.lineTo(484,264);ctx.lineTo(407,233);ctx.lineTo(390,246);ctx.lineTo(467,285);ctx.closePath();ctx.fillStyle='#d9bf8d';ctx.fill();for(let i=0;i<14;i++){let x=476+rand(i,9)*48,y=285+rand(i,10)*140;rect(x,y,5,3,'#c7ab79')}
// pond
rect(717,265,151,88,'#74b9bd');rect(730,254,123,15,'#74b9bd');rect(709,275,14,60,'#74b9bd');rect(728,272,121,7,'#8bd0cb');rect(744,296,27,3,'#b5e3d8');rect(809,322,35,3,'#9ad9d0');for(let i=0;i<9;i++){let x=718+i*17;rect(x,250+rand(i,5)*16,5,21,'#628b53');rect(x-3,250+rand(i,5)*9,11,5,'#83a869')}
// cottage
rect(190,123,174,113,'#f2dfb6');rect(178,224,193,10,'#9b7956');rect(184,155,8,78,'#e7d2a6');rect(198,166,35,29,'#91bfc1');rect(195,163,41,5,'#fff0c8');rect(211,166,4,29,'#fff0c8');rect(249,183,38,53,'#ad7555');rect(256,191,25,45,'#c1845e');rect(278,203,4,4,'#f4d276');rect(305,163,39,31,'#91bfc1');rect(301,159,47,5,'#fff0c8');rect(322,163,4,31,'#fff0c8');rect(193,124,170,11,'#aa7050');rect(210,99,124,36,'#aa7050');rect(222,88,103,23,'#bc7f55');rect(237,75,72,19,'#ca8b5a');rect(265,64,15,16,'#9d694d');rect(266,58,14,7,'#ded4b2');
// flowers by house
for(const [x,y,col] of [[155,215,'#eaa4aa'],[172,225,'#e9c85d'],[371,211,'#e8a7a5'],[382,228,'#fff1c8']]){rect(x,y,4,8,'#608950');rect(x-2,y-2,4,4,col);rect(x+2,y-2,4,4,'#fff0c0')}
// garden plots and crops
for(let i=0;i<3;i++){let x=406+i*74,y=292;rect(x-6,y+39,63,7,'#806143');rect(x,y,52,39,'#9e714b');rect(x+4,y+4,44,31,'#79543f');rect(x+6,y+7,40,25,'#835d43');let crop=state.crops[i];if(crop&&crop.seed){for(let j=0;j<3;j++){let px=x+12+j*12,py=y+21; if(crop.stage===0){rect(px+3,py-4,3,6,'#76a85f')}else if(crop.stage===1){rect(px+2,py-9,5,11,'#65a151');rect(px-3,py-6,5,3,'#8eb96b');rect(px+5,py-12,5,3,'#86b866')}else if(crop.stage===2){rect(px,py-12,8,14,'#5d964a');rect(px-5,py-9,6,4,'#8bbd67');rect(px+6,py-15,6,4,'#8bbd67');if(crop.watered)rect(px+1,py-15,4,4,'#d59b52')}else{rect(px+1,py-12,7,13,'#6d9c4a');rect(px+1,py-1,8,11,'#ef9b4c');rect(px+2,py+5,7,6,'#e98941');rect(px-4,py-12,6,4,'#8abb68')}}if(crop.watered)rect(x+2,y+32,47,2,'#83c3d0')}}
// fence
for(let x=45;x<166;x+=23){rect(x,238,5,49,'#e9d8b5');rect(x-2,244,10,5,'#d2ba92');rect(x-2,266,10,5,'#d2ba92')}rect(43,247,124,5,'#e9d8b5');rect(43,270,124,5,'#e9d8b5');
// large tree and chopped stump
rect(620,181,31,104,'#886345');rect(626,216,28,8,'#9d7550');rect(597,147,78,58,'#608952');rect(606,130,61,55,'#709a5e');rect(617,117,43,41,'#81a86b');rect(612,151,11,8,'#88b472');rect(652,172,8,6,'#80a56a');
// player pixel sprite
rect(551,292,17,18,'#f0c899');rect(548,289,23,9,'#806044');rect(545,308,28,25,'#d78069');rect(541,308,7,15,'#f0c899');rect(569,308,7,15,'#f0c899');rect(549,331,8,17,'#665747');rect(562,331,8,17,'#665747');rect(556,298,3,3,'#55453e');rect(564,298,3,3,'#55453e');rect(555,304,8,2,'#ba7458');
// bird specks and sun
rect(806,71,35,35,'#f4df8e');rect(813,65,21,6,'#f7e9ad');rect(810,106,28,5,'#f0d477');
}
function renderUI(){ $('#money').textContent=state.money;$('#daylabel').textContent=`Frühling · Tag ${state.day}`;$('#energy').textContent=state.energy;$('#clock').textContent=`${state.hour}:${String(state.minute).padStart(2,'0')} Uhr`;$('#townmood').textContent=state.day>4?'Richtig heimisch':'Willkommen!';$('#friendcount').textContent=Object.values(state.friends).filter(x=>x>0).length;$('#majalove').textContent=state.friends.Maja;$('#oskarlove').textContent=state.friends.Oskar;
$('#inventory').innerHTML=Object.entries(state.inventory).filter(([,n])=>n>0).slice(0,8).map(([k,n])=>`<div class="invitem"><b>${n}</b>${items[k]?.emoji||'📦'}<small>${items[k]?.name||k}</small></div>`).join('')||'<div class="empty" style="grid-column:span 4;text-align:center;padding:12px">Noch ist dein Rucksack leer. Los geht’s!</div>';
$('#invcount').textContent=`${Object.values(state.inventory).reduce((a,b)=>a+b,0)} / 12`;
$('#crops').innerHTML=state.crops.map((c,i)=>`<div class="cropbox"><span class="crop-emoji">${!c.seed?'🟫':c.stage===0?'🌱':c.stage===1?'🌿':c.stage===2?'🌾':'🥕'}</span><div style="min-width:0"><div class="cropname">${!c.seed?'Leeres Beet':c.stage>=3?'Erntebereit':`${items[c.seed].name} · ${c.watered?'gegossen':'wächst'}`}</div><div class="progress"><i style="width:${!c.seed?0:c.stage*33}%"></i></div></div></div>`).join('');
$('#log').innerHTML=state.logs.map(x=>`<div class="logline">✦ ${x}</div>`).join('');let done=state.quest>=3;$('#questtitle').textContent=done?'Majas Korb ist voll!':'Ein Korb voller Freude';$('#questdesc').textContent=done?'Wunderbar! Maja freut sich riesig.':`Bring Maja 3 Karotten · ${state.quest}/3`;$('#questprogress').style.width=`${Math.min(100,state.quest/3*100)}%`;$('#questreward').textContent=done?'✓ Erledigt':'+45 🪙';draw();}
renderUI();

