$('#restbtn').onclick=()=>{nextDay();};$('#soundbtn').onclick=()=>{const b=$('#soundbtn');b.textContent=b.textContent==='♫'?'♪':'♫';toast(b.textContent==='♪'?'Die Vögel zwitschern für dich. 🎶':'Die Dorfgeräusche sind jetzt leise.')};
