canvas.addEventListener('click',e=>{
 const r=canvas.getBoundingClientRect();
 const x=(e.clientX-r.left)/r.width*900;
 const y=(e.clientY-r.top)/r.height*440;
 const i=x>=400&&x<625&&y>=285&&y<350?Math.floor((x-406)/74):-1;
 if(i>=0&&i<3){
  const c=state.crops[i];
  if(state.tool==='plant'){
   if(c.seed){toast('Dieses Beet ist schon bepflanzt.');return}
   const seed=state.inventory.seed_carrot?'carrot':state.inventory.seed_turnip?'turnip':null;
   if(!seed){toast('Im Dorfladen gibt es frisches Saatgut.');return}
   if(!act())return;
   state.inventory['seed_'+seed]--;c.seed=seed;c.stage=0;c.watered=false;
   log(`${items[seed].name} gesät – jetzt heißt es pflegen!`);toast('Ein kleines Samenkorn ist gesetzt! 🌱');
  }else if(state.tool==='water'){
   if(!c.seed){toast('Hier wächst noch nichts. Säe erst ein Samenkorn.');return}
   if(c.watered){toast('Dieses Beet ist schon gegossen.');return}
   if(!act())return;
   c.watered=true;c.stage=Math.min(3,c.stage+1);log('Du hast deine Pflanzen gegossen.');
   toast(c.stage>=3?'Deine Karotten sind reif! 🥕':'Deine Pflanze wächst dankbar weiter. 💧');
  }else if(state.tool==='harvest'){
   if(!c.seed||c.stage<3){toast('Noch nicht reif – ein bisschen Geduld!');return}
   if(!act())return;
   const crop=c.seed;add(crop);
   log(`${items[crop].name} geerntet – frisch vom Hof!`);
   c.seed=null;c.stage=0;c.watered=false;toast(`${items[crop].emoji} Ernte im Rucksack!`);
  }else{
   toast(c.seed?`${items[c.seed].name} · ${c.stage>=3?'erntereif!':'wächst auf deinem Beet.'}`:'Ein freies Beet. Säe etwas Neues!');
  }
  save();return;
 }
 if(x>700&&y>245&&y<365)toast('Der See ist ein wunderbarer Ort zum Angeln. 🎣');
 else if(x>585&&x<690&&y>110&&y<290)toast('Der alte Baum wartet schon auf deine Axt. 🪓');
 else if(x>170&&x<380&&y>55&&y<245)toast('Dein gemütliches Zuhause. Hier kannst du nach einem langen Tag schlafen. 🏡');
 else toast('Überall im Sonnental gibt es etwas zu entdecken! 🌼');
});

