await page.locator('[data-tool="harvest"]').click();
const b=await scene.boundingBox();
await page.mouse.click(b.x+b.width*(430/900),b.y+b.height*(310/440));
const result=await page.evaluate(()=>({quest:JSON.parse(localStorage.getItem('hofglueck-save')).quest,carrots:JSON.parse(localStorage.getItem('hofglueck-save')).inventory.carrot,description:document.querySelector('#questdesc').textContent}));
